import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

edits.newText:
// --- Bricks: face bounce, push-out, corner, seam ---------------------------

// Top-face hit: the ball was overlapping the brick (sticky case), moving down
// into it. It must leave the brick upward, out of the rectangle, in one bounce.
// (ballSpeed(1)=260, dt=1/60: step 4.3 px, brick 20 high.)
test('brick: top-face hit kills the brick and bounces the ball out', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + brick.h / 2,
    r: BALL_R,
    vx: 0,
    vy: 300,
  };
  const lost = step(state, 1 / 60);
  assert.equal(lost, false);
  assert.equal(brick.alive, false, 'the brick must die on the first touch');
  assert.ok(state.ball.vy < 0, 'the ball must leave the brick upward');
  assert.ok(
    state.ball.y + state.ball.r <= brick.y,
    'the ball must be pushed fully out of the brick',
  );
});

// Corner hit: equal penetrations on both axes (12 px on each) must invert both
// components. dt = 0: no movement, a single resolution pass at the overlap.
test('brick: corner hit inverts both components and pushes the ball out', () => {
  const state = createState(1);
  const brick = state.bricks[6]; // row 0, col 6 at (484, 48)
  state.ball = { x: 551, y: 53, r: BALL_R, vx: 200, vy: 200 };
  step(state, 0);
  assert.ok(
    state.ball.vx < 0 && state.ball.vy < 0,
    'both components must invert at a corner',
  );
  assert.equal(collides(state.ball, brick), false);
});

// Seam: the 8 px gap between two columns is smaller than the 14 px ball, so a
// ball on the seam overlaps both bricks at once. Two flips of the same axis in
// one pass would cancel and let the ball through: exactly one brick may be
// resolved per pass.
test('brick: a seam overlap resolves with a single bounce per pass', () => {
  const state = createState(1);
  const left = state.bricks[3 * BRICK_COLS + 3]; // x 244..316
  const right = state.bricks[3 * BRICK_COLS + 4]; // x 324..396
  state.ball = { x: 321, y: 142, r: BALL_R, vx: -300, vy: 0 };
  step(state, 0);
  assert.equal(left.alive, false, 'the first brick of the seam is broken');
  assert.equal(right.alive, true, 'the second brick must not resolve in the same pass');
  assert.ok(state.ball.vx > 0, 'the velocity must flip exactly once');
});

// Tunneling: at level 6 a single 50 ms step is 35.5 px > brick 20 + ball 14,
// so a naive discrete step jumps the brick without ever overlapping it.
test('brick: no tunneling at level 6 with dt at the 50 ms cap', () => {
  const state = createState(6); // ballSpeed(6) = 710
  const brick = state.bricks[0];
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y - BALL_R - 0.1,
    r: BALL_R,
    vx: 0,
    vy: ballSpeed(6),
  };
  const lost = step(state, 0.05);
  assert.equal(lost, false);
  assert.equal(brick.alive, false, 'the ball must hit the brick, not jump over it');
  assert.ok(state.ball.vy < 0, 'the ball must bounce upward');
});

// --- Paddle: traversal, dead angle -----------------------------------------

// Paddle traversal: at level 5 a 50 ms step is 31 px > paddle 12 + ball 14, so
// the ball would jump the paddle band and fall through. It must exit upward.
test('paddle: no traversal from above at level 5 with dt at the 50 ms cap', () => {
  const state = createState(5); // ballSpeed(5) = 620
  state.ball = {
    x: WIDTH / 2,
    y: PADDLE_Y - BALL_R - 0.1,
    r: BALL_R,
    vx: 0,
    vy: ballSpeed(5),
  };
  const lost = step(state, 0.05);
  assert.equal(lost, false);
  assert.ok(state.ball.vy < 0, 'the ball must bounce back up');
  assert.ok(
    state.ball.y + state.ball.r <= PADDLE_Y,
    'the ball must exit from the top of the paddle',
  );
});

// Dead angle: hit === 0 at the paddle centre must not leave vx = 0 (a purely
// vertical trajectory is unplayable: it never reaches the side bricks).
test('paddle: a centre hit never leaves a dead vertical trajectory', () => {
  const state = createState(1);
  state.ball = {
    x: state.paddle.x + state.paddle.w / 2,
    y: PADDLE_Y - BALL_R - 1,
    r: BALL_R,
    vx: 0,
    vy: 300,
  };
  step(state, 1 / 60);
  assert.ok(Math.abs(state.ball.vx) > 0, 'vx must stay non-zero after a centre hit');
});

// --- Speed conservation & dt-independence ----------------------------------

// The norm of the velocity after a brick bounce is the level speed, whatever
// the incoming norm was (here hypot(150, 500) ~ 522 while ballSpeed(3) = 440).
test('brick: speed after a bounce equals the level speed', () => {
  const state = createState(3);
  const brick = state.bricks[0];
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y - BALL_R - 0.1,
    r: BALL_R,
    vx: 150,
    vy: 500,
  };
  step(state, 1 / 60);
  const mag = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(
    Math.abs(mag - ballSpeed(3)) < 1e-6,
    `speed ${mag.toFixed(3)} should be ${ballSpeed(3)}`,
  );
});

// The same 1 s of play must give the same outcome at 30 fps and 144 fps:
// same bricks broken, same velocity sign, ball not lost.
test('physics: same outcome at 30 fps and 144 fps', () => {
  function sim(fps, seconds) {
    const state = createState(1);
    const dt = 1 / fps;
    state.ball = { x: 280, y: 20, r: BALL_R, vx: 0, vy: ballSpeed(1) };
    let lost = false;
    for (let i = 0; i < Math.round(seconds * fps); i++) {
      lost = lost || step(state, dt);
    }
    return {
      lost,
      dead: state.bricks.filter((b) => !b.alive).map((b) => `${b.row}:${b.col}`).sort(),
      vy: state.ball.vy,
    };
  }
  const at30 = sim(30, 1);
  const at144 = sim(144, 1);
  assert.equal(at30.lost, false);
  assert.equal(at144.lost, false);
  assert.deepEqual(at30, at144);
});

// --- Score / combo ----------------------------------------------------------

// One kill = one brick scored once, combo incremented by one.
test('brick: one kill scores the brick once and increments the combo', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + brick.h / 2,
    r: BALL_R,
    vx: 0,
    vy: 300,
  };
  step(state, 1 / 60);
  assert.equal(state.combo, 1);
  assert.equal(state.score, scoreForBrick(brick, 1));
});

// The combo multiplier must saturate instead of blowing the score up.
test('score: combo multiplier is bounded', () => {
  assert.equal(comboMultiplier(100), 6);
  assert.equal(scoreForBrick({ points: 10 }, 100), Math.round(10 * 6));
});

// TODO      : test level progression and loadBest/saveBest persistence.

